INSERT INTO "sources" VALUES('senate18imm','/sessions/sharp-jolly-carson/mnt/Aus_Kanon/Audits/Hanson_Audit/Sources_Archive/senate18imm.txt','⚠️→🔧','⚠️→🔧','Cross-checked against 5+ Plane 1/2 header quotes: all genuine (verbatim matches in the archived 2018 immigration speech). BUT the same tag was also used for a fabricated quote ("I was imprisoned in 2003... held in maximum security on electoral fraud charges") shared across 3 Plane 5 nodes (The Whistleblower, The Courtroom, The Trial) — that sentence does not exist anywhere in this speech, which is entirely about immigration/population. Fixed: all 3 re-pointed to the real, already-verified `[^ms16]` imprisonment quote',9,NULL,'2026-07-09T18:43:36');
INSERT INTO "sources" VALUES('senate18prot','/sessions/sharp-jolly-carson/mnt/Aus_Kanon/Audits/Hanson_Audit/Sources_Archive/senate18prot.txt','fabricated','fabricated','Cited quote about RSL/bowls/sports clubs is FABRICATED — real speech (fetched in full) is entirely about immigration/burqa/Denmark integration, no mention of clubs at all. Fixed: The Club node now cites `[^tvfy]` instead.',7,NULL,'2026-07-09T18:43:36');
INSERT INTO "sources" VALUES('senate18tax','/sessions/sharp-jolly-carson/mnt/Aus_Kanon/Audits/Hanson_Audit/Sources_Archive/senate18tax.txt','verified','verified','Checked all 5 header quotes citing it in Plane 1/2 (The Bush, The Gold Rush, The Pub Test, The Union, Fiscal Equalization): all verbatim genuine. Also used this session for Plane 7 Biodiversity node (Effect.What.Cause) header quote, replacing a fabricated bracket placeholder, with the "Bruce Highway" line verified verbatim against the archive; the same speech''s dams/Bradfield/Ord/coal content also used in Biodiversity''s Actuality',21,NULL,'2026-07-09T18:43:36');
INSERT INTO "sources" VALUES('senate20jm','/sessions/sharp-jolly-carson/mnt/Aus_Kanon/Audits/Hanson_Audit/Sources_Archive/senate20jm.txt','verified','verified','Checked all header quotes citing it in Plane 1/3 (The Cycle, The Sickie, The Food Bowl, Goyder''s Line): all verbatim genuine',8,NULL,'2026-07-09T18:43:36');
INSERT INTO "sources" VALUES('senate21voice','/sessions/sharp-jolly-carson/mnt/Aus_Kanon/Audits/Hanson_Audit/Sources_Archive/senate21voice.txt','verified','verified','Checked all header quotes citing it in Plane 2/5/6 (The Interpreter, The Deal, The Great Silence, Relation, plus a body claim on Uluru/Foundation): all verbatim genuine',6,NULL,'2026-07-09T18:43:36');
INSERT INTO "sources" VALUES('tnd_ensuringintegrity','/sessions/sharp-jolly-carson/mnt/Aus_Kanon/Audits/Hanson_Audit/Sources_Archive/tnd_ensuringintegrity.txt','verified','verified','Confirmed verbatim: "But they''re coming out with a sledgehammer against the unions..."',1,NULL,'2026-07-09T18:43:36');
